{
  "definition_simple": "在比赛、竞争或斗争中取得胜利。",
  "definition_standard": "在竞赛、博弈、战斗或选举等具有对抗性的活动中，击败对手或取得优势而最终胜出。",
  "pos": "动词",
  "semantic_class": "action",
  "sentences": [
    {
      "sentence": "我们队在昨天的足球比赛中获胜了。",
      "tier": "T1"
    },
    {
      "sentence": "谁能在明天的决赛中获胜，谁就是今年的冠军。",
      "tier": "T2"
    },
    {
      "sentence": "他们凭借默契的团队配合，最终以微弱优势获胜。",
      "tier": "T3"
    },
    {
      "sentence": "只要大家在下半场不放弃，我们依然有希望获胜。",
      "tier": "T3"
    },
    {
      "sentence": "在激烈的辩论赛中，正方论证严密、反驳有力，成功获胜。",
      "tier": "T4"
    },
    {
      "sentence": "尽管面对实力强劲的卫冕选手，这名年轻黑马依然沉着应战并爆冷获胜。",
      "tier": "T4"
    },
    {
      "sentence": "竞选团队通过精准的选民数据画像与动员策略，协助候选人在关键摇摆州获胜。",
      "tier": "T5"
    },
    {
      "sentence": "该项争议提案在股东大会上以压倒性多数票获胜，得以如期落地推行。",
      "tier": "T5"
    },
    {
      "sentence": "在瞬息万变的高频算法博弈中，指令响应速度哪怕仅领先微秒者亦能获胜，进而攫取超额利润。",
      "tier": "T6"
    },
    {
      "sentence": "这场旷日持久的跨国知识产权诉讼终见分晓，原告凭借扎实的底层代码溯源证据艰难获胜。",
      "tier": "T6"
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "l1_audio_confusables": [
    {
      "word": "获释",
      "explanation": "拼音为 huòshì，声母及韵母与 huòshèng 接近（声调同为第四声），但意为被羁押者获得释放，语义完全不同。"
    },
    {
      "word": "获赠",
      "explanation": "拼音为 huòzèng，韵母相同且声调皆为去声，在部分不分平翘舌（z/sh）的方言区听觉上极易混淆，其意为得到赠予。"
    },
    {
      "word": "活生",
      "explanation": "拼音为 huóshēng，声韵母完全相同，仅声调由去声变为阳平和阴平，发音稍有不慎即会引发听音误判。"
    }
  ],
  "primary_collocate": "最终",
  "collocation_distractors": [
    {
      "word": "打败",
      "explanation": "“打败”本身是及物动词或述补结构，不可充当副词来修饰不及物动词“获胜”。"
    },
    {
      "word": "战胜",
      "explanation": "“战胜”与“获胜”语义同质且为及物动词，两词不可直接叠置搭配形成修饰关系。"
    },
    {
      "word": "优胜",
      "explanation": "“优胜”通常作定语（如“优胜者”）或状态名词，不作状语修饰动词“获胜”。"
    }
  ],
  "collocation_wrong_collocate": "全面",
  "cloze_distractors": [
    {
      "word": "战胜",
      "explanation": "“战胜”是及物动词，后面必须带受事宾语（如“战胜对手”），不可在句末无宾语独立作谓语。"
    },
    {
      "word": "赢取",
      "explanation": "“赢取”侧重于获得具体的奖品或荣誉（如“赢取奖金”），在此语境中缺乏宾语且语义侧重点偏离胜利结果。"
    },
    {
      "word": "成全",
      "explanation": "“成全”意为帮助他人达到某种目的，语义与本队比赛取得胜利完全不相关。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "我们队在最后的决赛中以三比零获胜了对手。",
      "explanation": "及物性错误。“获胜”是不及物动词，不能直接带人或队伍等受事宾语，应使用及物动词“战胜/击败”或改说“战胜对手而获胜”。"
    },
    {
      "sentence": "他凭借平时的刻苦努力，终于获胜了这次期末考试。",
      "explanation": "语义与搭配对象错误。“获胜”适用于对抗性竞技、争端或诉讼，不能与非博弈性质的标准测试（如“考试”）搭配，应改为“通过了考试”。"
    },
    {
      "sentence": "这场比赛虽然打得十分艰苦，但最终被主队获胜了。",
      "explanation": "语态结构错误。“获胜”表示主动赢得竞争的自主行为，不能用于被动句中充当被动动词谓语（“比赛被获胜”不合语法规则）。"
    }
  ],
  "spot_incorrect": {
    "sentence": "经过两个小时的鏖战，中国女排最终以三比二获胜了巴西队。",
    "error_description": "“获胜”为不及物动词，后不可直接加受事宾语“巴西队”，应使用及物动词“击败”或“战胜”，或者在宾语前加介词“战胜巴西队获胜”。",
    "corrected_sentence": "经过两个小时的鏖战，中国女排最终以三比二战胜了巴西队。"
  },
  "word_family_forms": [
